import{_ as t,o,c as r,ag as a}from"./chunks/framework.2cFhd8Ux.js";const m=JSON.parse('{"title":"Team Project Milestones","description":"","frontmatter":{"source":"project/milestones.md"},"headers":[],"relativePath":"project/milestones.md","filePath":"project/milestones.md"}'),n={name:"project/milestones.md"};function s(i,e,d,h,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="team-project-milestones" tabindex="-1">Team Project Milestones <a class="header-anchor" href="#team-project-milestones" aria-label="Permalink to &quot;Team Project Milestones&quot;">​</a></h1><blockquote><p>Every team-project deadline and deliverable is defined here, once. Week pages copy these rows; if they ever disagree, this page counts.</p></blockquote><p>Unless Canvas says otherwise, each deliverable is <strong>due before next week&#39;s Seminar (default 11:59 pm the night before)</strong>. At each milestone deadline, staff record your team fork&#39;s <code>main</code> commit and its open branches and PRs, and grade that <strong>snapshot</strong>. One member submits the team fork&#39;s URL on Canvas. Course documents live in the fork&#39;s <code>course/</code> folder (<a href="./#where-things-live">why</a>).</p><h2 id="milestones-at-a-glance" tabindex="-1">Milestones at a glance <a class="header-anchor" href="#milestones-at-a-glance" aria-label="Permalink to &quot;Milestones at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Due</th><th>Points</th><th>What it shows</th><th>Rubric</th></tr></thead><tbody><tr><td><strong>M0: proposal</strong></td><td>End of week 5 (before the week 6 Seminar)</td><td>15</td><td>You know the codebase well enough to plan a contribution you can verify</td><td><a href="./../assessment/rubrics.html#m0-proposal">M0</a></td></tr><tr><td><strong>M1: first PR</strong></td><td>End of week 8 (before the week 9 Seminar)</td><td>30</td><td>Every member can get a tested, reviewed change through the team&#39;s process</td><td><a href="./../assessment/rubrics.html#m1-first-pr">M1</a></td></tr><tr><td><strong>M2: major contribution</strong></td><td>End of week 12 (before the week 13 Seminar)</td><td>40</td><td>The team can deliver a substantial, verified, secured contribution</td><td><a href="./../assessment/rubrics.html#m2-major-contribution">M2</a></td></tr><tr><td><strong>Final</strong></td><td>Start of the final exam period (week 16)</td><td>45</td><td>The contribution works, and its evidence is reproducible</td><td><a href="./../assessment/rubrics.html#final-report-and-repository">Final</a> and <a href="./final-presentation.html#rubric">presentation</a></td></tr></tbody></table><p>For CS [4xxx] that is about M0 4.0% · M1 8.1% · M2 10.8% · Final 12.1% of the course grade; for CS [5xxx] the same points scale to 30% in all.</p><h2 id="the-full-timeline" tabindex="-1">The full timeline <a class="header-anchor" href="#the-full-timeline" aria-label="Permalink to &quot;The full timeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Due</th><th>What</th><th>Graded as</th></tr></thead><tbody><tr><td>1</td><td>During the week</td><td>Team-formation survey on Canvas</td><td>—</td></tr><tr><td>2</td><td>Before the week 3 Seminar</td><td><code>course/TEAM_CHARTER.md</code> in your team fork</td><td>Checked at M0 (Team setup row)</td></tr><tr><td>3</td><td>Before the week 4 Seminar</td><td>Your <code>AGENTS.md</code> A/B test (individual assignment); the team merges one <code>AGENTS.md</code> for the fork by M0</td><td>Week 3 assignment; M0</td></tr><tr><td>4</td><td>Before the week 5 Seminar</td><td><code>course/THREAT_MODEL.md</code> for your team&#39;s agent setup (part of the week 4 assignment)</td><td>Week 4 assignment; M0</td></tr><tr><td>5</td><td>Before the week 6 Seminar</td><td><strong>M0: proposal</strong></td><td>M0 rubric</td></tr><tr><td>8</td><td>Before the week 9 Seminar</td><td><strong>M1: first PR</strong>; peer evaluation 1 on Canvas; PR-round preparation (<a href="./pr-round.html#before-the-round">The PR Round: Before the round</a>)</td><td>M1 rubric</td></tr><tr><td>9</td><td>Before the week 10 Seminar</td><td>Your PR-round PR opened on your assigned fork</td><td><a href="./../assessment/rubrics.html#the-pr-round">PR round</a></td></tr><tr><td>10</td><td>Before the week 11 Seminar</td><td>PR round closes: your team&#39;s reviews and decisions on received PRs; your responses to the review you received</td><td>PR round</td></tr><tr><td>12</td><td>Before the week 13 Seminar</td><td><strong>M2: major contribution</strong>; peer evaluation 2 on Canvas</td><td>M2 rubric</td></tr><tr><td>12–15</td><td>Any time</td><td>Optional upstream PRs; the first one screened by staff (the week 14 Lab, or office hours)</td><td>Bonus only (<a href="./contribution-rules.html">rules</a>)</td></tr><tr><td>13</td><td>Before the week 14 Seminar</td><td>Your team&#39;s process retrospective with data (the week 13 assignment)</td><td>Week 13 assignment; used in the final report</td></tr><tr><td>14</td><td>Before the week 15 Seminar</td><td><strong>Final report draft</strong> on Canvas</td><td>Feedback; a missing draft costs 3 points of the Final</td></tr><tr><td>15</td><td>In the week 15 Lab</td><td>Presentation dry run</td><td>Practice, not graded</td></tr><tr><td>16</td><td>Start of the final exam period</td><td>The <strong>repository snapshot</strong> (your fork&#39;s <code>main</code>, which staff tag <code>final</code>), the <strong>final report</strong> and peer evaluation 3 on Canvas</td><td>Final rubric</td></tr><tr><td>16</td><td>The final exam period</td><td><strong>The final presentation</strong></td><td><a href="./final-presentation.html#rubric">Presentation rubric</a></td></tr></tbody></table><p>The team token can extend M0, M1 or M2 by 48 hours; nothing extends the PR round or the Final (<a href="./../assessment/#late-work-and-grace-tokens">late work</a>).</p><h2 id="m0-proposal" tabindex="-1">M0: proposal <a class="header-anchor" href="#m0-proposal" aria-label="Permalink to &quot;M0: proposal&quot;">​</a></h2><p><strong>End of week 5 · 15 points · Team.</strong> Your plan for the semester, grounded in what you observed during onboarding.</p><ul><li>☐ <strong>A feature area and 3–6 issues</strong> in the class codebase, at least one owned by each member. Each issue (in your team fork, linked from <code>course/TASKS.md</code>) has a reproduction or a user story, and a &quot;done when&quot;. Use existing upstream issues where they fit, and say where each came from.</li><li>☐ <strong><code>course/SPEC.md</code></strong> (<a href="./../templates/SPEC.html">template</a>): acceptance criteria in EARS form (for example &quot;WHEN a recurring session is cancelled THE agent SHALL…&quot;), each checkable; at least two edge cases; constraints (compatibility, performance, no new dependencies without a reason); how each criterion will be verified; an out-of-scope list.</li><li>☐ <strong><code>course/DESIGN.md</code></strong> (<a href="./../templates/DESIGN.html">template</a>): the modules and files you&#39;ll change, observed from your onboarding reports; one alternative design and why you didn&#39;t pick it; risks with a fallback.</li><li>☐ <strong><code>course/TASKS.md</code></strong> (<a href="./../templates/TASKS.html">template</a>): agent-sized tasks with an owner each, a Specify · Delegate · Verify line each, and your targets for M1 and M2.</li><li>☐ <strong>Team setup:</strong> <code>course/TEAM_CHARTER.md</code> current; one <code>AGENTS.md</code> for the fork (from your week 3 work); <code>course/THREAT_MODEL.md</code> (from week 4); <code>main</code> protected so that changes need a PR with one approval; the fork&#39;s README says how to build and test it.</li></ul><p>The instructor replies on Canvas within a week with <strong>Go</strong>, <strong>Shrink</strong> (go, with a smaller scope) or <strong>Rethink</strong> (let&#39;s talk before you build).</p><h2 id="m1-first-pr" tabindex="-1">M1: first PR <a class="header-anchor" href="#m1-first-pr" aria-label="Permalink to &quot;M1: first PR&quot;">​</a></h2><p><strong>End of week 8 · 30 points: Individual 18, Team 12.</strong> Every member gets a real change through the team&#39;s whole process once, early, while there&#39;s time to fix the process.</p><p><strong>Each member:</strong></p><ul><li>☐ <strong>One PR to the team fork</strong> that resolves (or clearly advances) one of your M0 issues. It may be merged or still open, but it must have been reviewed.</li><li>☐ <strong>Tests that fail without the change</strong>, with a link to the failing run or commit; characterization tests first wherever you touched code that had none; CI green on the PR.</li><li>☐ <strong>A description you wrote yourself</strong> (🔴 AI off): what, why, how you verified it, the risks; the AI disclosure section filled in; <code>Assisted-by: [tool and model]</code> trailers on AI-assisted commits; the issue linked.</li><li>☐ <strong>A review received and answered:</strong> a teammate reviewed it using the <a href="./../templates/REVIEW.html">REVIEW template</a>, and you answered every comment with a change or a reason.</li><li>☐ <strong>A review given:</strong> you reviewed a teammate&#39;s M1 PR with located comments.</li><li>☐ <strong>Peer evaluation 1</strong> on Canvas (🔴 AI off).</li></ul><p><strong>The team:</strong></p><ul><li>☐ CI runs the project&#39;s tests on every PR and is green on <code>main</code>; <code>main</code> is protected; the fork builds in a fresh Codespace from its README.</li><li>☐ <code>course/TASKS.md</code> and the issues are current, and the M2 target is revised with what M1 taught you.</li><li>☐ <code>course/AI_LOG.md</code> has a Specify · Delegate · Verify entry for every M1 PR, with what verification caught.</li><li>☐ <strong>PR-round preparation</strong> (<a href="./pr-round.html#before-the-round">details</a>): at least as many <code>eswa-pr-round</code> issues as your team has members, plus one.</li></ul><h2 id="m2-major-contribution" tabindex="-1">M2: major contribution <a class="header-anchor" href="#m2-major-contribution" aria-label="Permalink to &quot;M2: major contribution&quot;">​</a></h2><p><strong>End of week 12 · 40 points: Team 24, Individual 16.</strong> The substantial piece of work your M0 proposed, verified to the standard of weeks 6–12.</p><p><strong>The team:</strong></p><ul><li>☐ <strong>The contribution</strong> implements <code>course/SPEC.md</code> as revised, with a status table (met, partial, not met) that matches the code.</li><li>☐ <strong>Verification:</strong> tests for every criterion; property-based tests wherever the logic has invariants; the mutation score of the changed modules with the command, the score and every surviving mutant explained (equivalent mutants identified); CI gates for tests, lint and CodeQL or Semgrep, all green. No test skipped or deleted to get there.</li><li>☐ <strong>Security review:</strong> the week 10 review applied to the contribution; findings fixed with regression tests or justified in writing; <code>course/THREAT_MODEL.md</code> updated; a history-aware secret scan clean.</li><li>☐ <strong>Evals, if the contribution uses an LLM:</strong> <code>course/EVAL_PLAN.md</code> (<a href="./../templates/EVAL_PLAN.html">template</a>), an eval set, a judge reported with percent agreement and Cohen&#39;s κ, and a CI gate that runs on recorded responses. <strong>If it doesn&#39;t:</strong> <code>course/DESIGN.md</code> updated with two decisions, the alternatives you rejected and the evidence for each.</li></ul><p><strong>Each member:</strong></p><ul><li>☐ At least one <strong>substantive PR you authored</strong> that is part of the contribution, tested, described by you and disclosed.</li><li>☐ At least <strong>two reviews</strong> of teammates&#39; M2 PRs, with located comments.</li><li>☐ Your M2 sessions in <code>course/AI_LOG.md</code>, with what was delegated and what your checks caught.</li><li>☐ <strong>Peer evaluation 2</strong> on Canvas (🔴 AI off).</li></ul><h2 id="final" tabindex="-1">Final <a class="header-anchor" href="#final" aria-label="Permalink to &quot;Final&quot;">​</a></h2><p><strong>Start of the final exam period · 45 points, all Team: report and repository 35, presentation 10.</strong></p><h3 id="the-repository-snapshot" tabindex="-1">The repository snapshot <a class="header-anchor" href="#the-repository-snapshot" aria-label="Permalink to &quot;The repository snapshot&quot;">​</a></h3><p>Your team fork&#39;s <code>main</code> at the <strong>start of the final exam period</strong>, which staff tag <code>final</code> and grade, so merge everything you want graded before then. From it, a grader must be able to:</p><ul><li>☐ build the fork in a fresh Codespace from its README;</li><li>☐ run <strong>one documented command or CI workflow</strong> that reproduces your tests, mutation scores, scans and (if any) evals;</li><li>☐ find every course document in <code>course/</code>, current.</li></ul><h3 id="the-final-report" tabindex="-1">The final report <a class="header-anchor" href="#the-final-report" aria-label="Permalink to &quot;The final report&quot;">​</a></h3><p>On <strong>Canvas</strong>, by the start of the final exam period, as one PDF or Markdown file of about 2,000–3,500 words plus tables and figures. 🟡 <strong>AI limited:</strong> AI may help with tables, figures and checking claims against the fork; the sections marked 🔴 are written by your team with the AI off.</p><ol><li><strong>Summary:</strong> what you contributed to the class codebase, in one paragraph.</li><li><strong>Status against the spec:</strong> the criteria table (met, partial, not met), matching the tagged commit.</li><li><strong>How to reproduce:</strong> the command or workflow, and what it should print.</li><li><strong>Evidence:</strong> tests, mutation scores (with survivors), CI gates, security findings, evals. Every number must be reproducible from the snapshot.</li><li><strong>Two engineering decisions:</strong> each with the alternatives, the evidence, and what you&#39;d watch for.</li><li><strong>Process and AI use:</strong> a summary of <code>course/AI_LOG.md</code> (what you delegated, what verification caught, with examples, what the agents couldn&#39;t do), and the data from your week 13 retrospective.</li><li><strong>Honest limitations</strong> (🔴): known issues, threats to the validity of your own numbers, what you&#39;d do next.</li><li><strong>Contributions</strong> (🔴): a table by GitHub username of who built and reviewed what, with PR numbers.</li><li><strong>Reflection</strong> (🔴): what your team would do differently, and why.</li></ol><p>The week 14 <strong>draft</strong> has the same outline, with sections 2–6 filled in as far as they can be; staff comment on it before the week 15 Lab.</p><h3 id="the-final-presentation-and-peer-evaluation-3" tabindex="-1">The final presentation and peer evaluation 3 <a class="header-anchor" href="#the-final-presentation-and-peer-evaluation-3" aria-label="Permalink to &quot;The final presentation and peer evaluation 3&quot;">​</a></h3><ul><li>☐ <strong>The final presentation</strong> in the final exam period: ten minutes per team, with a live demo (<a href="./final-presentation.html">The Final Presentation</a>).</li><li>☐ <strong>Peer evaluation 3</strong> on Canvas (🔴 AI off), by the start of the final exam period.</li></ul><h2 id="peer-evaluations" tabindex="-1">Peer evaluations <a class="header-anchor" href="#peer-evaluations" aria-label="Permalink to &quot;Peer evaluations&quot;">​</a></h2><p>With M1, M2 and the Final, each member rates every teammate and themselves on Canvas (🔴 AI off), with a sentence of evidence for each rating (<a href="./../assessment/rubrics.html#peer-evaluation">criteria</a>). Ratings are seen only by staff. They can adjust a member&#39;s share of the team rows only when the repository evidence agrees, and only after the member has seen a summary of the concerns and had a chance to respond (<a href="./../assessment/#team-grades-and-peer-evaluation">the process</a>). A missing peer evaluation costs you 2 points of that milestone.</p>',38)])])}const f=t(n,[["render",s]]);export{m as __pageData,f as default};
